            !warnings
                .iter()
                .any(|w| w.contains("CARGO_REGISTRY_TOKEN") && !w.contains("REGISTRIES")),
            "should NOT warn about bare CARGO_REGISTRY_TOKEN for private-registry crates, got: {:?}",
