26	    fn package_name(&self) -> Result<String, ManifestError>;
27	    fn current_version(&self) -> Result<Version, ManifestError>;
28	    fn write_version(&mut self, v: &Version, permit: &ApplyPermit) -> Result<(), ManifestError>;
29	    fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError>;
30	    fn iter_dependencies(&self) -> Box<dyn Iterator<Item = callisto_model::DependencyEntry> + '_>;
31	    fn update_dependency_spec(
32	        &mut self,
33	        name: &str,
34	        kind: callisto_model::DepKind,
35	        new: DepSpec,
36	        permit: &ApplyPermit,
37	    ) -> Result<(), ManifestError>;
38	    fn is_publishable(&self) -> bool {
39	        true
40	    }
41	    fn publish_targets(&self) -> Vec<callisto_model::PublishTarget> {
42	        if !self.is_publishable() {
43	            return vec![callisto_model::PublishTarget::None];
44	        }
45	        match self.ecosystem() {
46	            Ecosystem::Cargo => vec![callisto_model::PublishTarget::CratesIo],
47	            Ecosystem::Npm => vec![callisto_model::PublishTarget::Npm {
48	                registry: None,
49	                access: None,
50	            }],
51	            _ => vec![callisto_model::PublishTarget::None],
52	        }
53	    }
54	    fn update_optional_dependencies(
55	        &mut self,
56	        updates: &[(String, Version)],
57	        permit: &ApplyPermit,
58	    ) -> Result<(), ManifestError>;
59	}
