68	/// Test-observability counter: total number of times [`open`] has been
69	/// invoked. Production code never reads this; it exists so callers (in
70	/// particular, callers building a caching layer on top of `open()`) can
71	/// write regression tests asserting that a given manifest path is opened
72	/// (read + parsed from disk) at most once per logical operation, instead of
73	/// once per call site. See `callisto-graph`'s `manifest_cache` module.
74	static OPEN_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
75	
76	/// Resets the internal manifest-open call counter to zero. Intended for use in test setup.
77	pub fn reset_open_call_count() {
78	    OPEN_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
79	}
80	
81	/// Reads the current value of the internal manifest-open call counter.
82	pub fn open_call_count() -> usize {
83	    OPEN_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
84	}
85	
86	/// Test-observability counter: total number of times a `Manifest`
87	/// implementor's `persist` has returned `Ok`. Production code never reads
88	/// this; it exists so callers can write regression tests asserting a given
89	/// manifest path is flushed to disk at most once per logical operation.
90	/// Distinct from `OPEN_CALL_COUNT` so open-count and persist-count
91	/// assertions in the same test are independent.
92	static PERSIST_CALL_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
93	
94	/// Resets the internal manifest-persist call counter to zero. Intended for use in test setup.
95	pub fn reset_persist_call_count() {
96	    PERSIST_CALL_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
97	}
98	
99	/// Reads the current value of the internal manifest-persist call counter.
100	pub fn persist_call_count() -> usize {
101	    PERSIST_CALL_COUNT.load(std::sync::atomic::Ordering::SeqCst)
102	}
103	
104	/// Increments PERSIST_CALL_COUNT by one. Called by each Manifest
105	/// implementor's persist() immediately after its own atomic_write returns
106	/// Ok; PERSIST_CALL_COUNT itself is private to this module, so this is the
107	/// only way other modules in this crate may increment it.
108	pub(crate) fn record_persist_call() {
109	    PERSIST_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
110	}
