112	/// Opens a manifest file matching `decl.format`.
113	pub fn open(decl: &ManifestDecl, ctx: &OpenContext<'_>) -> Result<Box<dyn Manifest>, ManifestError> {
114	    OPEN_CALL_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
115	    if decl.role == ManifestRole::Lockfile {
116	        return Err(ManifestError::ReadOnlyFormat {
117	            path: decl.path.clone(),
118	            format: decl.format,
119	            reason: "lockfiles are regenerated via subprocess (§7.6 step 9), never opened as a Manifest handle",
120	        });
121	    }
122	
123	    match decl.format {
124	        #[cfg(feature = "cargo")]
125	        ManifestFormat::CargoToml => Ok(Box::new(CargoToml::open(decl, ctx)?)),
126	        #[cfg(feature = "npm")]
127	        ManifestFormat::PackageJson => Ok(Box::new(PackageJson::open(decl, ctx)?)),
128	        #[cfg(feature = "pypi")]
129	        ManifestFormat::PyprojectToml => Ok(Box::new(PyprojectToml::open(decl, ctx)?)),
130	        other => Err(ManifestError::ReadOnlyFormat {
131	            path: decl.path.clone(),
132	            format: other,
133	            reason: "not implemented — demand-gated per §2.2",
134	        }),
135	    }
136	}
