138	/// Dispatches spec round-trip rewriting to the appropriate ecosystem handler.
139	pub fn round_trip(ecosystem: Ecosystem, spec: &DepSpec, target: &Version) -> Option<DepSpec> {
140	    match (ecosystem, spec) {
141	        #[cfg(feature = "cargo")]
142	        (Ecosystem::Cargo, _) => cargo::round_trip(spec, target),
143	        #[cfg(feature = "npm")]
144	        (Ecosystem::Npm, _) => npm::round_trip(spec, target),
145	        #[cfg(feature = "pypi")]
146	        (Ecosystem::Pypi, _) => python::round_trip(spec, target),
147	        _ => None,
148	    }
149	}
