161	        fs::write(
162	            dir.path().join("pyproject.toml"),
163	            "[project]\nname = \"demo-pkg\"\nversion = \"1.2.3\"\n",
164	        )
165	        .unwrap();
166	
167	        let decl = ManifestDecl {
168	            path: PathBuf::from("pyproject.toml"),
169	            role: ManifestRole::Canonical,
170	            format: ManifestFormat::PyprojectToml,
171	        };
172	        let ctx = OpenContext {
173	            workspace_root: dir.path(),
174	            cargo_workspace: None,
175	            npm_workspace_kind: None,
