178	        let manifest = open(&decl, &ctx).expect("open() should dispatch PyprojectToml to PyprojectToml::open");
179	        assert_eq!(manifest.ecosystem(), Ecosystem::Pypi);
180	        assert_eq!(manifest.role(), ManifestRole::Canonical);
181	        assert_eq!(manifest.package_name().unwrap(), "demo-pkg");
182	        assert_eq!(manifest.current_version().unwrap().render(), "1.2.3");
